import json
import joblib
import numpy as np

from sklearn.ensemble import RandomForestClassifier
from sklearn.preprocessing import LabelEncoder

from natasha import (
    Segmenter,
    MorphVocab,
    NewsEmbedding,
    NewsMorphTagger,
    NewsSyntaxParser,
    NewsNERTagger,
    Doc
)


# ============================================================
# NLP INIT
# ============================================================

segmenter = Segmenter()
morph_vocab = MorphVocab()

emb = NewsEmbedding()

morph_tagger = NewsMorphTagger(emb)
syntax_parser = NewsSyntaxParser(emb)
ner_tagger = NewsNERTagger(emb)


# ============================================================
# LABEL ENCODERS
# ============================================================

pos_encoder = LabelEncoder()
rel_encoder = LabelEncoder()

ALL_POS = [
    "NOUN", "VERB", "ADJ", "ADV",
    "PROPN", "ADP", "CCONJ",
    "SCONJ", "DET", "PRON",
    "PART", "INTJ", "NUM",
    "PUNCT", "X", ""
]

ALL_REL = [
    "root", "nsubj", "obj", "obl",
    "amod", "nmod", "case",
    "conj", "cc", "punct",
    "advmod", "appos", ""
]

pos_encoder.fit(ALL_POS)
rel_encoder.fit(ALL_REL)


# ============================================================
# MAIN CLASS
# ============================================================

class NewsEventFinder:

    def __init__(self):

        self.model = RandomForestClassifier(
            n_estimators=300,
            max_depth=12,
            random_state=42
        )

        self.is_trained = False

    # ========================================================
    # WORD FEATURES
    # ========================================================

    def get_word_features(self, token):

        grammemes = []

        if token.feats:
            for key, value in token.feats.items():
                grammemes.append(f"{key}={value}")

        return [
            token.text,
            token.lemma if token.lemma else "",
            token.pos if token.pos else "",
            grammemes,
            len(token.text),
            token.text.isalpha(),
            token.text.isdigit(),
            token.text.istitle(),
            token.rel if token.rel else ""
        ]

    # ========================================================
    # CONTEXT
    # ========================================================

    def get_context(self, tokens, index, window=3):

        result = []

        # BEFORE
        for offset in range(window, 0, -1):

            pos = index - offset

            if pos >= 0:
                result.append(
                    self.get_word_features(tokens[pos])
                )
            else:
                result.append(None)

        # AFTER
        for offset in range(1, window + 1):

            pos = index + offset

            if pos < len(tokens):
                result.append(
                    self.get_word_features(tokens[pos])
                )
            else:
                result.append(None)

        return result

    # ========================================================
    # ENTITY EXTRACTION
    # ========================================================

    def extract_entities(self,title,subTitle,mainText):

        text = title + ". " + subTitle + ". " + mainText

        doc = Doc(text)

        doc.segment(segmenter)

        doc.tag_morph(morph_tagger)

        doc.parse_syntax(syntax_parser)

        doc.tag_ner(ner_tagger)

        for token in doc.tokens:
            token.lemmatize(morph_vocab)

        entities = []

        for span in doc.spans:

            if span.type not in ["LOC", "ORG"]:
                continue

            span.normalize(morph_vocab)

            entity_tokens = []

            for i, token in enumerate(doc.tokens):

                if (
                    token.start >= span.start
                    and token.stop <= span.stop
                ):
                    entity_tokens.append((i, token))

            if not entity_tokens:
                continue

            first_index = entity_tokens[0][0]

            context = self.get_context(
                doc.tokens,
                first_index
            )

            entity = {
                "entity_type": span.type,
                "entity_name": span.text,
                "entity_normal": (
                    span.normal
                    if span.normal
                    else span.text
                ),

                "data": [

                    context[0],
                    context[1],
                    context[2],

                    span.text,

                    context[3],
                    context[4],
                    context[5]
                ]
            }

            entities.append(entity)

        return entities

    # ========================================================
    # WORD -> VECTOR
    # ========================================================

    def word_to_vector(self, word_features):

        if word_features is None:
            return [0] * 10

        word = word_features[0]
        lemma = word_features[1]
        pos = word_features[2]
        grammemes = word_features[3]
        length = word_features[4]
        is_alpha = word_features[5]
        is_digit = word_features[6]
        is_title = word_features[7]
        rel = word_features[8]

        try:
            pos_encoded = pos_encoder.transform([pos])[0]
        except:
            pos_encoded = 0

        try:
            rel_encoded = rel_encoder.transform([rel])[0]
        except:
            rel_encoded = 0

        return [

            pos_encoded,

            rel_encoded,

            length,

            int(is_alpha),

            int(is_digit),

            int(is_title),

            int(word.isupper()),

            int(word.istitle()),

            len(lemma),

            len(grammemes)
        ]

    # ========================================================
    # ENTITY -> VECTOR
    # ========================================================

    def entity_to_features(self, entity):

        data = entity["data"]

        vector = []

        # BEFORE
        for i in range(3):
            vector.extend(
                self.word_to_vector(data[i])
            )

        # ENTITY
        entity_name = data[3]

        vector.extend([

            len(entity_name),

            int(entity_name.istitle()),

            int(entity["entity_type"] == "LOC"),

            int(entity["entity_type"] == "ORG")
        ])

        # AFTER
        for i in range(4, 7):
            vector.extend(
                self.word_to_vector(data[i])
            )

        return np.array(vector)

    # ========================================================
    # TRAIN
    # ========================================================

    def train(
        self,
        train_file="json_data/train.json"
    ):

        with open(train_file,"r",encoding="utf-8") as f:
            train_data = json.load(f)

        X = []
        y = []

        for item in train_data:

            features = self.entity_to_features(item)

            X.append(features)

            y.append(item["label"])

        X = np.array(X)
        y = np.array(y)

        self.model.fit(X, y)

        self.is_trained = True

        print("MODEL TRAINED")

    def save_model(self,model_path="models/news_finder.pkl"):

        joblib.dump(self.model,model_path)

        print("MODEL SAVED")


    def load_model(self,model_path="models/news_finder.pkl"):

        self.model = joblib.load(model_path)

        self.is_trained = True

        print("MODEL LOADED")

    # ========================================================
    # PREDICT ONE ENTITY
    # ========================================================

    def predict_event_place(
        self,
        entity
    ):

        if not self.is_trained:
            raise Exception(
                "MODEL IS NOT TRAINED"
            )

        features = self.entity_to_features(
            entity
        )

        probability = self.model.predict_proba(
            [features]
        )[0][1]

        return float(probability)

    # ========================================================
    # FIND MAIN EVENT PLACE
    # ========================================================

    def define_place(self,title,subTitle,mainText):

        entities = self.extract_entities(title,subTitle,mainText)

        if len(entities) == 0:
            return None

        best_entity = None

        best_probability = 0

        for entity in entities:

            probability = self.predict_event_place(
                entity
            )

            entity["probability"] = probability

            if probability > best_probability:

                best_probability = probability

                best_entity = entity

        return best_entity


# ============================================================
# GLOBAL INIT
# ============================================================

news_finder = None


# ============================================================
# API
# ============================================================

def init_news_finder():

    global news_finder

    news_finder = NewsEventFinder()

    return news_finder


